settings.custom_css:
selector .sep {
  display: inline-block;
  font-size: 0;
  line-height: 0;
  margin: 0 14px;
  vertical-align: middle;
}

selector .sep::before {
  content: "";
  display: block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #FEB100;
}

selector .gb-modulo{position:relative}
selector .gb-acc .e-n-accordion-item-title{width:fit-content;transition:background .2s,color .2s}
selector .gb-intro{margin:0 0 24px;color:#0F1629}
selector .gb-s{margin:0 0 22px}
selector .gb-s:last-child{margin-bottom:0}
@media (min-width:768px){selector .gb-acc{margin-top:-67px}selector .gb-acc .e-n-accordion-item-title{align-self:flex-end}}
@media (max-width:767px){
selector .gb-acc{margin-top:16px}
selector .gb-acc .e-n-accordion-item-title{width:100%;justify-content:center}
selector .gb-s{margin:0;padding:16px 0;border-top:1px solid #D9DCE4}
selector .gb-s:first-child{border-top:0;padding-top:8px}
selector .gb-intro{margin:0 0 6px}
selector .gb-sn{display:block;font-size:16px;margin-bottom:2px}
selector .gb-dot{display:none}
}
